function chanceNoneFail(p, n) {
  return Math.pow(1 - p, n);
}

function chanceAtLeastOne(p, n) {
  return 1 - Math.pow(1 - p, n);
}

function expectedFlaws(n, p) {
  return n * p;
}

function chanceBothFail(p, q) {
  return p * q;
}

function chanceEitherFails(p, q) {
  return 1 - (1 - p) * (1 - q);
}

function riskPercent(n, perEntryPercent) {
  const p = perEntryPercent / 100;
  const atLeastOne = 1 - Math.pow(1 - p, n);
  return Math.round(atLeastOne * 1000) / 10;
}

function entryPointsToReach(targetPercent, perEntryPercent) {
  const p = perEntryPercent / 100;
  const target = targetPercent / 100;
  let n = 1;
  while (1 - Math.pow(1 - p, n) < target) {
    n += 1;
  }
  return n;
}

function riskAfterRetiring(n, retired, perEntryPercent) {
  const remaining = n - retired;
  const p = perEntryPercent / 100;
  const atLeastOne = 1 - Math.pow(1 - p, remaining);
  return Math.round(atLeastOne * 1000) / 10;
}
